using System;using System.Reflection;using System.Linq;
class Program{static string Encode(string s)=>string.Concat(s.Select(c=>((int)c).ToString("x4")));static void Main(){var method=typeof(Uri).GetMethod("PrivateParseMinimal",BindingFlags.Instance|BindingFlags.NonPublic);var flagsField=typeof(Uri).GetField("_flags",BindingFlags.Instance|BindingFlags.NonPublic);var stringField=typeof(Uri).GetField("_string",BindingFlags.Instance|BindingFlags.NonPublic);var originalField=typeof(Uri).GetField("_originalUnicodeString",BindingFlags.Instance|BindingFlags.NonPublic);var syntaxField=typeof(Uri).GetField("_syntax",BindingFlags.Instance|BindingFlags.NonPublic);var flagsType=typeof(Uri).GetNestedType("Flags",BindingFlags.NonPublic);var file=typeof(UriParser).GetField("FileUri",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);var unix=typeof(UriParser).GetField("UnixFileUri",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);string line;while((line=Console.ReadLine())!=null){var p=line.Split(' ');ulong flags=ulong.Parse(p[0]);int syntax=int.Parse(p[1]);string text="";if(p[2]!="-")for(int i=0;i<p[2].Length;i+=4)text+=(char)Convert.ToUInt16(p[2].Substring(i,4),16);var uri=new Uri("file:///x");flagsField.SetValue(uri,Enum.ToObject(flagsType,flags));stringField.SetValue(uri,text);originalField.SetValue(uri,text);syntaxField.SetValue(uri,syntax!=0?unix:file);var error=method.Invoke(uri,null);Console.WriteLine($"{Convert.ToInt32(error)}:{Convert.ToUInt64(flagsField.GetValue(uri))}:{(ReferenceEquals(syntaxField.GetValue(uri),unix)?1:0)}:{Encode((string)stringField.GetValue(uri))}");}}}
